function bounds(set){const arr=[...set].map(parseKey);if(!arr.length)return{minX:0,minY:0,maxX:0,maxY:0,w:1,h:1};const xs=arr.map(v=>v[0]),ys=arr.map(v=>v[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);return{minX,minY,maxX,maxY,w:maxX-minX+1,h:maxY-minY+1}}
function squareShape(n){const s=new Set();for(let x=0;x<n;x++)for(let y=0;y<n;y++)s.add(key(x,y));return s}
