function renderReference(demo=false){const f=family(),box=$('referenceStage');box.innerHTML='';$('referenceCaption').textContent='';if(f.id==='ambiguity'){box.appendChild(makeRefGrid(state.refShape));$('referenceValue').textContent='Stage 3 · 6 squares';return}const shape=f.shape(state.currentStage),prev=state.currentStage>1?f.shape(state.currentStage-1):new Set(),growth=diffSet(prev,shape);box.appendChild(makeRefGrid(shape,growth,demo));$('referenceValue').textContent=`Stage ${state.currentStage} · ${shape.size} squares`}
function maxShapeForFamily(f){return f.shape(f.maxStage)}
function buildAnchorFor(shape){const b=bounds(shape);return{x:Math.floor((GRID_COLS-b.w)/2)-b.minX,y:Math.floor((GRID_ROWS-b.h)/2)-b.minY}}
function buildKeyFromModel(k){const a=buildAnchorFor(maxShapeForFamily(family())),[x,y]=parseKey(k);return key(x+a.x,y+a.y)}
