function targetGrowthSet(){const f=family();if(f.id==='ambiguity')return null;const cur=f.shape(state.currentStage),next=f.shape(state.currentStage+1);return new Set([...diffSet(cur,next)].map(buildKeyFromModel))}
function ghostSet(){const f=family();if(f.id==='ambiguity'){const b=bounds(state.refShape),a={x:Math.floor((GRID_COLS-b.w)/2)-b.minX,y:Math.floor((GRID_ROWS-b.h)/2)-b.minY};return new Set([...state.refShape].map(k=>{const[x,y]=parseKey(k);return key(x+a.x,y+a.y)}))}return new Set([...f.shape(state.currentStage)].map(buildKeyFromModel))}
