function renderTray(){const used=new Set(state.placed.values()),field=$('looseField');field.innerHTML='';for(let i=1;i<=MAX_TILES;i++){const id=`tile-${i}`,b=document.createElement('button');b.type='button';b.className='loose-tile'+(used.has(id)?' used':'');b.dataset.tileId=id;b.setAttribute('aria-label',`Loose square ${i}`);bindTile(b,'loose');field.appendChild(b)}}
function validTargetCell(k){const f=family();return f.id==='ambiguity'?validAmbiguityCell(k):targetGrowthSet().has(k)&&!state.placed.has(k)}
